//! 2.0: the public `ExactNumArray` entry points that take a precision reject `p = 0`
//! (`MIN_PRECISION` is 1): every element of the result is `NaN(InvalidArgument)`, or an
//! `Option` result is `None`. Each call is also run at `p = 64` as a control, which must not
//! give `InvalidArgument`, so a pass cannot come from the operands alone.
//! Generated by /tmp/zf-logs/gen_p0_array.py. `ExactNumArray::new(p)` (an empty array, no
//! element to carry the error) and the feature-gated `random_fill` are not covered.

use zenith_float_num::{Consts, Error, ExactNum, ExactNumArray, RoundingMode, Word};

fn invalid(x: &ExactNum) -> bool {
    x.err() == Some(Error::InvalidArgument)
}

fn bad(a: &ExactNumArray) -> bool {
    !a.is_empty() && a.as_slice().iter().all(invalid)
}

fn bad_opt(a: &Option<ExactNumArray>) -> bool {
    a.as_ref().is_none_or(bad)
}

fn bad_pair(a: &(ExactNumArray, ExactNumArray)) -> bool {
    bad(&a.0) && bad(&a.1)
}

fn bad_opt_pair(a: &Option<(ExactNumArray, ExactNumArray)>) -> bool {
    a.as_ref().is_none_or(bad_pair)
}

fn any_invalid(a: &ExactNumArray) -> bool {
    a.as_slice().iter().any(invalid)
}

fn ok(a: &ExactNumArray) -> bool {
    !a.is_empty() && !any_invalid(a)
}

fn ok_opt(a: &Option<ExactNumArray>) -> bool {
    a.as_ref().is_some_and(ok)
}

fn ok_pair(a: &(ExactNumArray, ExactNumArray)) -> bool {
    ok(&a.0) && ok(&a.1)
}

fn ok_opt_pair(a: &Option<(ExactNumArray, ExactNumArray)>) -> bool {
    a.as_ref().is_some_and(ok_pair)
}

fn q(n: Word, d: Word) -> ExactNum {
    ExactNum::from_word(n, 64).div(&ExactNum::from_word(d, 64), 64, RoundingMode::ToEven)
}

